import struct

# 16x16 favicon: Catppuccin Mocha base with a blue ">" prompt and a cursor bar.
BASE, BLUE = (0x2e, 0x1e, 0x1e, 0xff), (0xfa, 0xb4, 0x89, 0xff)  # BGRA
px = [[BASE] * 16 for _ in range(16)]
for x, y in [(4,4),(5,5),(6,6),(7,7),(6,8),(5,9),(4,10),
             (5,6),(6,7),(5,8),                      # thicken the chevron
             (9,10),(10,10),(11,10)]:                # cursor bar
    px[y][x] = BLUE

# BMP rows are bottom-up inside an ICO.
bits = b"".join(b"".join(bytes(c) for c in row) for row in reversed(px))
mask = b"\x00" * (4 * 16)  # 16x16 1bpp AND mask, padded to 4-byte rows
header = struct.pack("<IiiHHIIiiII", 40, 16, 32, 1, 32, 0, len(bits), 0, 0, 0, 0)
image = header + bits + mask
ico = struct.pack("<HHH", 0, 1, 1) + struct.pack("<BBBBHHII", 16, 16, 0, 0, 1, 32, len(image), 22) + image
open("favicon.ico", "wb").write(ico)
print("favicon.ico", len(ico), "bytes")
